import { chromium } from 'playwright';
import { mkdir, writeFile } from 'node:fs/promises';
const out='artifacts/reference-error-diagnostic';await mkdir(out,{recursive:true});const errors=[];const browser=await chromium.launch({headless:true,args:['--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});const context=await browser.newContext({viewport:{width:393,height:800},isMobile:true,hasTouch:true,deviceScaleFactor:3,userAgent:'Mozilla/5.0 (Linux; Android 15; sdk_gphone64_x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.6998.39 Mobile Safari/537.36'});const page=await context.newPage();page.on('pageerror',e=>{const d={at:new Date().toISOString(),url:page.url(),message:e.message,name:e.name,stack:e.stack};errors.push(d);console.error('REFERENCE_PAGE_ERROR '+JSON.stringify(d));});
const organs=['aorta','rca_artery','thymus','uterus','lad_artery','celiac_trunk','stomach','spinal_cord','placenta','brain','spleen','prostate','peripheral_nerves'];
try{for(const organ of organs){const url='https://orbitmbbs.vercel.app/simulator?'+new URLSearchParams({mode:'anatomy',organ,isolate:organ,nativeTheme:'dark',native_audit:'1'});console.log('Diagnostic route '+organ);await page.goto(url,{waitUntil:'domcontentloaded',timeout:90000});await page.waitForTimeout(15000);await writeFile(out+'/reference-page-errors.json',JSON.stringify({diagnosticOnly:true,organ,errors},null,2));}}finally{await writeFile(out+'/reference-page-errors.json',JSON.stringify({diagnosticOnly:true,errors},null,2));await browser.close();}
